"""Offline HTML catalogue and individual named mesh exports."""
from model import *
from html import escape
import shutil

def main():
    parts=load_parts(GEOM/'reference_parts.npz');out=ROOT/'parts'/'models';out.mkdir(exist_ok=True)
    index=json.loads((ROOT/'parts'/'index.json').read_text())
    for p,item in zip(parts,index):
        name=f'{item["index"]:02d}_{p.name}.glb';export_glb([p],out/name);item['model']='models/'+name
    (ROOT/'parts'/'index.json').write_text(json.dumps(index,indent=2))
    style='''*{box-sizing:border-box}body{margin:0;background:#0c1219;color:#dce6ee;font:16px/1.6 system-ui,sans-serif}main{max-width:1400px;margin:auto;padding:30px}h1{font-size:clamp(26px,4vw,50px);line-height:1.15}h2{margin-top:56px}p{max-width:900px;color:#a5b5c4}a{color:#93c6e5}nav{display:flex;gap:20px;flex-wrap:wrap;margin:25px 0}input,select{padding:13px;color:#e1e9f0;background:#17212b;border:1px solid #364655;border-radius:5px}input{width:min(500px,95%)}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(270px,1fr));gap:20px}.card{margin:0;background:#101922;border:1px solid #253240;border-radius:8px;overflow:hidden}.card img{width:100%;display:block}.card figcaption{padding:14px}.card h3{font-size:16px;line-height:1.35;margin:0 0 7px}.small{font-size:13px;color:#8fa2b3}.views{display:grid;grid-template-columns:repeat(auto-fit,minmax(450px,1fr));gap:22px}video,.hero{width:100%;border:1px solid #253240;border-radius:8px}.note{border-left:3px solid #aa8359;padding:12px 20px;background:#171c22}.buttons{display:flex;gap:12px;flex-wrap:wrap}.buttons a{padding:8px 14px;border:1px solid #344653;border-radius:5px;text-decoration:none}@media(max-width:650px){main{padding:18px}.views{grid-template-columns:1fr}}'''
    cards=[]
    for item in index:
        n=item['name'];dims=' x '.join(f'{d:.2f}' for d in item['size_mm'])
        cards.append(f'''<figure class="card" data-name="{escape((n+' '+item['group']).lower())}"><a href="parts/{item['image']}"><img loading="lazy" src="parts/{item['image']}" alt="Individual 3D render of {escape(n)}"></a><figcaption><h3>{item['index']:02d} / {escape(n.replace('_',' '))}</h3><div class="small">Bounding box: {dims} mm<br>{item['triangles']:,} triangles</div><a href="parts/{item['model']}">Open this individual GLB mesh</a></figcaption></figure>''')
    view_names=[('pt_exploded.png','Original model, exploded'),('pt_internal.png','Original internal assembly'),('pt_section.png','Longitudinal geometric section'),('clutch_bearing_detail.png','Clutch, spring and bearing separation'),('pt_kinematic_core.png','Separate paired-pinion kinematic core'),('working_section.png','New core in the preserved exterior')]
    views=''.join(f'<figure class="card"><a href="renders/{f}"><img loading="lazy" src="renders/{f}" alt="{escape(t)}"></a><figcaption>{escape(t)}</figcaption></figure>' for f,t in view_names)
    html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TORSEN-X / Geometry Inspection v3</title><style>{style}</style></head><body><main><div class="small">GEOMETRY INSPECTION V3 / OFFLINE PACKAGE</div><h1>Inside the reconstruction.</h1><p>New internal, sectioned, exploded and individual-part renders of the existing 81-component model, plus an explicitly separate 44-component kinematic-core redesign.</p><nav><a href="#motion">Motion video</a><a href="#views">Internal & exploded views</a><a href="#parts">All 81 parts</a><a href="#geometry">Animated geometry</a><a href="README.md">Engineering notes</a></nav><div class="note">The original geometry is preserved. Its visual core has no connecting pinion train. The new core is a gear-constrained rigid-body model, not a torque-bias, contact-force or manufacturing simulation. Its different internals are not an exact reconstruction of the generated concept image.</div><h2 id="motion">Motion, not a still-image pan</h2><video controls preload="metadata" poster="videos/motion_frame_0216.png"><source src="videos/TORSEN_X_full_inspection.mp4" type="video/mp4"></video><p>35 seconds at 1280 x 720, 24 fps. Explode and reassemble; equal outputs; split output speeds; one output held; carrier held; central coupling close-up; fixed-camera motion verification.</p><div class="buttons"><a href="videos/01_exploded_inspection.mp4">12-second exploded inspection</a><a href="videos/02_differential_in_motion.mp4">19-second differential demonstration</a><a href="videos/03_fixed_camera_motion.mp4">4-second fixed-camera check</a></div><h2 id="views">Internal & exploded views</h2><div class="views">{views}</div><h2 id="geometry">Animated geometry</h2><p>These standard glTF 2.0 files include actual transformation channels. Units are metres, Y up. Playback and part isolation depend on the viewer used.</p><div class="buttons"><a href="geometry/reference_explosion_animated.glb">Original model / animated explosion</a><a href="geometry/kinematic_core_animated.glb">New core / animated mechanism</a><a href="geometry/working_variant_animated.glb">Original shell + new core / animation</a></div><p><a href="validation/kinematic_checks.json">600 sampled gear-section checks and mesh checks</a> · <a href="validation/frame_kinematics.csv">Frame-by-frame angular states</a> · <a href="validation/animated_glb_checks.json">Animation export checks</a></p><h2 id="parts">All 81 original components</h2><p>Every card is an independently rendered source mesh. Repeated bearing balls and machining-line components remain individually indexed; these are mesh components, not a validated manufacturing bill of materials.</p><input id="search" type="search" placeholder="Filter by name: flange, spline, gear, ball, spring..."><p id="count">81 components</p><div class="grid" id="cards">{''.join(cards)}</div><p class="small">No external network resources are required. Open index.html from the extracted package. This page contains no generated concept images.</p></main><script>const input=document.getElementById('search');const cards=[...document.querySelectorAll('#cards .card')];input.addEventListener('input',()=>{{let n=0;for(const c of cards){{const show=c.dataset.name.includes(input.value.toLowerCase());c.hidden=!show;c.style.display=show?'':'none';if(show)n++;}}document.getElementById('count').textContent=n+' components';}});</script></body></html>'''
    (ROOT/'index.html').write_text(html)
    # Preserve the six analytic STEP bodies from the previous source archive.
    original=Path('/mnt/data/rebuild_source/TORSEN_X_reference_rebuild/geometry');dest=GEOM/'reference_step';dest.mkdir(exist_ok=True)
    for p in original.glob('*.step'):shutil.copy2(p,dest/p.name)
    print('HTML CATALOG + 81 INDIVIDUAL GLBS COMPLETE')
if __name__=='__main__':main()
